function loadLazyTranslationFile(key, loader, propNames, initialValues) {
  return loadLazyFile(key, {
    load: (await loader()),
    onSuccess: function onSuccess(data) {
      if (data == null) return initialValues;

      propNames.forEach(function(propName) {
        if (typeof data[propName] === 'undefined') {
          data[propName] = initialValues[propName];
        }
      });

      return data;
    }
  }).then(function(result) {
    return {
      alt: result,
      supportedLocaleData: result,
      downloaded: true,
      translated: result != null
    };
  });
}

